/**
 * Legal notices, Arabic (ar): formal Modern Standard Arabic DRAFTS of the base notice, the audience blocks and the
 * jurisdiction blocks. review: every string here is reasonable MSA but needs a native legal/editorial check.
 * They claim no licence, registration or regulatory status; entity facts are {{placeholders}} (see en.js).
 */
const NAMES = {
  IR: "إيران",
  SA: "المملكة العربية السعودية",
  AE: "الإمارات العربية المتحدة",
  GB: "المملكة المتحدة",
  EU: "الاتحاد الأوروبي والمنطقة الاقتصادية الأوروبية",
  US: "الولايات المتحدة الأمريكية",
  SG: "سنغافورة",
  MY: "ماليزيا",
  ID: "إندونيسيا",
};

export const JURISDICTION = [
  "للقرّاء في {name}: هذه المادة موجّهة فقط إلى {{audience_{k}}}، وليست موجّهة إلى غيرهم في {name} ولا يجوز لهم الاعتماد عليها.",
  "لا يُعدّ أي جزء من هذه المادة عرضًا أو دعوة أو ترويجًا في {name} لشراء أي منتج أو خدمة أو بيعه أو الاكتتاب فيه، أو لإبرام أي اتفاق. وقد لا تكون المنتجات والخصائص الموصوفة هنا متاحة في {name}.",
  "{{regulatory_statement_{k}}}",
];

const fill = (t, v) => t.replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m));

export const jurisdiction = (code, name) => {
  const k = code.toLowerCase();
  return { title: name, paragraphs: JURISDICTION.map((t) => fill(t, { name, k })) };
};

